const CAMPOS_EDITAVEIS = [
    "titulo", "isbn", "ano_publicacao", "quantidade",
    "autor_id", "editora_id", "categoria_id"
];

async function atualizarParcial(id, dados) {
    // as chaves fora da lista sao descartadas
    const campos = Object.keys(dados)
        .filter(campo => CAMPOS_EDITAVEIS.includes(campo));

    if (campos.length === 0) {
        const erro = new Error("Nenhum campo valido para atualizar.");
        erro.status = 400;
        throw erro;
    }

    const sets = campos.map(campo => `${campo} = ?`).join(", ");
    const valores = campos.map(campo => dados[campo]);

    const sql = `UPDATE livros SET ${sets} WHERE id = ?`;
    const [resultado] = await db.execute(sql, [...valores, id]);

    return resultado.affectedRows > 0;
}

