// livroModel.js
async function listarComPaginacao(page, limit) {
    const offset = (page - 1) * limit;

    const [rows] = await db.query(
        `SELECT l.id, l.titulo, a.nome AS autor
         FROM livros l
         INNER JOIN autores a ON l.autor_id = a.id
         LIMIT ? OFFSET ?`,
        [limit, offset]
    );

    const [[{ total }]] = await db.query("SELECT COUNT(*) AS total FROM livros");

    return {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit),
        data: rows
    };
}

// GET /livros?autor=Machado&page=2&limit=10
async function listarComFiltro(autor, page, limit) {
    const offset = (page - 1) * limit;
    const filtro = `%${autor}%`;

    const [rows] = await db.query(
        `SELECT l.titulo, a.nome AS autor
         FROM livros l
         INNER JOIN autores a ON l.autor_id = a.id
         WHERE a.nome LIKE ?
         LIMIT ? OFFSET ?`,
        [filtro, limit, offset]
    );

    return rows;
}

